"""Crop knowledge base (22 crops). General guidance only - not a prescription."""
# (name, description, soil, ph_min, ph_max, t_min, t_max, r_min, r_max, period, cultivation, fertilizer, irrigation)
CROPS = [
 ("Rice","Staple cereal grown in flooded fields; loves warm, humid weather.","Clay, Loamy, Alluvial Soil",5.5,7.0,20,35,150,300,"3–6 months, depending on variety","Raise a nursery, transplant 20–25 day old seedlings, keep fields levelled and weed-free.","Balanced NPK with nitrogen split into 2–3 doses; add zinc if leaves show deficiency.","Keep 2–5 cm standing water during most growth stages; drain before harvest."),
 ("Maize","Versatile cereal used for food, fodder and industry.","Loamy, Sandy, Alluvial Soil, Red Soil",5.8,7.0,18,32,60,110,"3–4 months","Sow in rows about 60 cm apart; weed during the first 30–40 days.","Nitrogen-rich feeding in 2–3 splits with a basal phosphorus dose.","Irrigate at knee-high stage, tasselling and grain filling; avoid waterlogging."),
 ("Chickpea","Cool-season pulse crop rich in protein.","Loamy, Black Soil, Sandy",6.0,8.0,15,28,60,100,"3–5 months","Sow after monsoon on well-drained soil; treat seeds with Rhizobium culture.","Needs little nitrogen (legume); phosphorus and sulphur help yield.","1–2 light irrigations at flowering and pod filling; sensitive to excess water."),
 ("Kidney Beans","Bean crop grown for protein-rich dry seeds and pods.","Loamy, Alluvial Soil",5.5,6.5,15,25,60,150,"3–4 months","Sow on well-drained soil; provide support for climbing varieties.","Moderate phosphorus and potassium; light nitrogen.","Regular light irrigation; avoid water stress at flowering."),
 ("Pigeon Peas","Hardy, drought-tolerant pulse (red gram / toor dal).","Red Soil, Loamy, Black Soil",5.0,7.0,18,35,100,200,"5–9 months","Often intercropped with cereals; thin plants after establishment.","Starter dose of phosphorus; legume fixes its own nitrogen.","Needs few irrigations; critical at flowering and pod set."),
 ("Moth Beans","Very drought-tolerant short-duration pulse of dry regions.","Sandy, Loamy",6.0,8.0,24,35,30,75,"2–3 months","Broadcast or line-sow at monsoon onset; needs little care.","Small phosphorus dose; usually no nitrogen needed.","Usually rain-fed; one irrigation in prolonged dry spells."),
 ("Mung Bean","Fast-growing pulse (green gram) that also improves soil.","Loamy, Sandy, Alluvial Soil",6.2,7.5,25,35,35,80,"2–3 months","Sow in rows 30 cm apart; keep weeds down in first month.","Low nitrogen; phosphorus at sowing.","1–3 light irrigations; avoid waterlogging."),
 ("Black Gram","Short-duration pulse (urad dal) grown in warm weather.","Loamy, Black Soil, Clay",6.0,8.0,25,35,50,100,"2.5–3.5 months","Sow with adequate spacing; remove weeds at 20 and 40 days.","Phosphorus at sowing; Rhizobium seed treatment is helpful.","Irrigate at flowering and pod formation if rain is short."),
 ("Lentil","Cool-season pulse (masoor) valued for protein.","Loamy, Sandy, Alluvial Soil",6.0,8.0,15,30,30,70,"3–4 months","Sow in rows in cool season; avoid water-logged fields.","Low nitrogen; phosphorus and potassium at sowing.","1–2 irrigations at branching and pod filling."),
 ("Pomegranate","Hardy fruit tree with good returns in semi-dry climates.","Loamy, Sandy, Red Soil",5.5,7.5,18,30,60,150,"6–7 months from flowering to fruit; trees bear after 2–3 years","Plant grafted saplings, prune regularly and mulch around the base.","Organic manure plus balanced NPK in split doses through the year.","Drip irrigation is ideal; avoid irregular watering, which cracks fruit."),
 ("Banana","Tropical fruit crop that needs warmth and steady moisture.","Loamy, Alluvial Soil, Clay",5.5,7.0,20,33,80,160,"10–12 months","Plant healthy suckers or tissue-culture plants; remove extra suckers.","Heavy feeder: nitrogen and potassium in frequent small doses plus manure.","Regular irrigation (drip preferred); good drainage is essential."),
 ("Mango","Popular tropical fruit tree; needs a dry spell before flowering.","Loamy, Alluvial Soil, Red Soil",5.5,7.5,24,35,50,150,"Fruits in 3–5 months after flowering; trees bear after 4–5 years","Plant grafted varieties; prune for light and airflow.","Manure plus NPK in split doses after harvest and before flowering.","Irrigate young trees regularly; reduce water just before flowering."),
 ("Grapes","Fruit vine grown on trellises; needs warm, dry ripening season.","Loamy, Sandy, Red Soil",5.5,7.0,15,30,50,100,"4–5 months from pruning to harvest","Train vines on trellis; prune twice a year as locally advised.","Organic manure with balanced NPK; potassium improves fruit quality.","Drip irrigation; limit water near ripening to improve quality."),
 ("Watermelon","Warm-season trailing fruit that needs sandy, well-drained soil.","Sandy, Loamy",6.0,7.0,22,32,40,100,"2.5–3.5 months","Sow on raised beds with wide spacing; mulch to control weeds.","Nitrogen early, potassium during fruit development.","Regular light irrigation; reduce water as fruits ripen."),
 ("Muskmelon","Sweet melon needing heat, sunshine and low humidity during ripening.","Sandy, Loamy, Alluvial Soil",6.0,7.0,24,34,20,60,"2.5–3.5 months","Sow on ridges or beds; use mulch and keep fruit off wet soil.","Balanced NPK; extra potassium for sweetness.","Frequent light irrigation, less near harvest."),
 ("Apple","Temperate fruit tree for cool hilly regions.","Loamy, Silt",5.5,6.5,15,25,80,150,"5–6 months from flowering to harvest; trees bear after 3–5 years","Needs winter chilling; train and prune trees annually.","Farmyard manure with NPK; calcium and boron as locally advised.","Regular irrigation in dry spells; ensure good drainage."),
 ("Orange","Citrus fruit tree for warm, sub-tropical climates.","Loamy, Sandy, Red Soil",6.0,7.5,13,30,80,150,"7–9 months from flowering to fruit","Plant grafted saplings with wide spacing; control citrus pests.","Manure plus NPK in 2–3 splits; micronutrients like zinc may help.","Irrigate regularly; avoid water standing around the trunk."),
 ("Papaya","Fast-growing tropical fruit; sensitive to waterlogging and frost.","Loamy, Sandy, Alluvial Soil",6.0,7.0,25,38,100,200,"9–12 months to first harvest","Raise seedlings in bags; plant on mounds with excellent drainage.","Frequent small doses of N, P, K plus organic manure.","Light, regular irrigation; never allow water to stand."),
 ("Coconut","Tall palm of coastal tropical regions.","Sandy, Loamy, Alluvial Soil, Red Soil",5.5,7.0,22,32,130,230,"Palms bear after 5–7 years; nuts mature in about 12 months","Plant in pits with manure; leave wide spacing; mulch with husks.","Manure plus NPK and potash in two splits yearly.","Basin or drip irrigation in dry months."),
 ("Cotton","Major fibre crop for warm climates with a dry harvest season.","Black Soil, Loamy, Alluvial Soil",6.0,8.0,21,30,60,120,"5–6 months","Sow in rows on well-drained soil; monitor regularly for bollworms.","Nitrogen in splits with phosphorus and potassium; avoid over-feeding nitrogen.","Irrigate at square formation, flowering and boll development."),
 ("Jute","Natural fibre crop of warm, humid, high-rainfall regions.","Alluvial Soil, Loamy, Clay",6.0,7.5,24,35,150,250,"4–5 months","Fine seedbed, line sowing and timely thinning; retting after harvest.","Nitrogen in two splits with phosphorus and potash.","Mostly rain-fed; irrigate in early dry spells."),
 ("Coffee","Shade-loving plantation crop of cool, humid highlands.","Loamy, Red Soil",6.0,7.0,20,28,120,200,"Bushes bear after 3–4 years; cherries ripen in 8–9 months","Grow under shade trees; prune bushes and mulch to hold moisture.","Organic manure and NPK split across the year as locally advised.","Blossom/backing showers or sprinkler irrigation; keep soil moist, not wet."),
]
